-- =============================================================================
-- Nestap core schema · PostgreSQL 16
--
-- One schema per owning service. Foreign keys only WITHIN a schema; references
-- across schemas are logical (commented "-> schema.table") so each schema can
-- move to its own cluster later without rewriting the model.
--
-- IDs: uuid (UUIDv7 generated by the application, so ids sort by creation time;
-- gen_random_uuid() is only a fallback default). Device and product ids are short
-- text ids because they appear in MQTT topics and firmware.
-- Secrets: *_enc columns hold envelope-encrypted bytes (KMS/Vault data key,
-- AES-256-GCM). Plaintext secrets never reach the database.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE SCHEMA IF NOT EXISTS infra;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS catalog;
CREATE SCHEMA IF NOT EXISTS home;
CREATE SCHEMA IF NOT EXISTS device;
CREATE SCHEMA IF NOT EXISTS automation;
CREATE SCHEMA IF NOT EXISTS ota;
CREATE SCHEMA IF NOT EXISTS notify;
CREATE SCHEMA IF NOT EXISTS integration;

-- -----------------------------------------------------------------------------
-- infra: shared helpers
-- -----------------------------------------------------------------------------

CREATE FUNCTION infra.touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- Transactional outbox. While services share one cluster they share this table,
-- tagged by source_service; when a schema moves out, it takes its own copy.
CREATE TABLE infra.outbox (
  id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source_service text        NOT NULL,
  topic          text        NOT NULL,           -- Kafka topic
  key            text        NOT NULL,           -- Kafka partition key
  event_type     text        NOT NULL,
  payload        jsonb       NOT NULL,
  headers        jsonb       NOT NULL DEFAULT '{}',
  created_at     timestamptz NOT NULL DEFAULT now(),
  published_at   timestamptz
);
CREATE INDEX outbox_unpublished_idx ON infra.outbox (id) WHERE published_at IS NULL;

-- -----------------------------------------------------------------------------
-- catalog: vendors, apps, categories, products, thing model   (service: catalog)
-- -----------------------------------------------------------------------------

CREATE TABLE catalog.vendors (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL,
  kind        text NOT NULL DEFAULT 'oem' CHECK (kind IN ('platform', 'oem', 'partner')),
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

-- White-label mobile apps (each OEM brand can ship its own app on the platform).
CREATE TABLE catalog.apps (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id        uuid NOT NULL REFERENCES catalog.vendors (id),
  name             text NOT NULL,
  ios_bundle_id    text UNIQUE,
  android_package  text UNIQUE,
  config           jsonb NOT NULL DEFAULT '{}',  -- theme, feature flags, support links
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE catalog.categories (
  code          text PRIMARY KEY,                -- 'switch', 'socket', 'light', 'curtain', 'sensor.pir', 'gateway'
  parent_code   text REFERENCES catalog.categories (code),
  name          text NOT NULL,
  standard_dps  jsonb NOT NULL DEFAULT '[]',     -- standard DP codes a product in this category should expose
  voice_traits  jsonb NOT NULL DEFAULT '{}'      -- mapping to Alexa/Google capabilities
);

CREATE TABLE catalog.products (
  id                  text PRIMARY KEY,          -- pid, 16 chars base32, flashed into firmware
  vendor_id           uuid NOT NULL REFERENCES catalog.vendors (id),
  category_code       text NOT NULL REFERENCES catalog.categories (code),
  name                text NOT NULL,
  model               text NOT NULL,             -- vendor model number, e.g. 'D60-2G'
  connectivity        text NOT NULL CHECK (connectivity IN
                        ('wifi', 'wifi_ble', 'ble', 'ble_mesh', 'zigbee', 'ethernet', 'matter')),
  is_gateway          boolean NOT NULL DEFAULT false,
  auth_mode           text NOT NULL DEFAULT 'hmac' CHECK (auth_mode IN ('hmac', 'x509')),
  thing_model_version integer NOT NULL DEFAULT 1,
  panel               jsonb NOT NULL DEFAULT '{}',  -- app UI layout hints, i18n DP labels
  icon_url            text,
  status              text NOT NULL DEFAULT 'development'
                        CHECK (status IN ('development', 'released', 'retired')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX products_vendor_idx ON catalog.products (vendor_id);

-- The thing model: one row per data point (DP) of a product.
CREATE TABLE catalog.datapoints (
  product_id     text     NOT NULL REFERENCES catalog.products (id) ON DELETE CASCADE,
  dp_id          smallint NOT NULL CHECK (dp_id BETWEEN 1 AND 255),
  code           text     NOT NULL,              -- 'switch_1', 'countdown_1', 'cur_power', 'relay_status'
  name           text     NOT NULL,
  kind           text     NOT NULL DEFAULT 'property' CHECK (kind IN ('property', 'event')),
  type           text     NOT NULL CHECK (type IN
                   ('bool', 'value', 'enum', 'string', 'bitmap', 'raw', 'json')),
  mode           text     NOT NULL CHECK (mode IN ('rw', 'ro', 'wo')),
  -- value:  {"min":0,"max":86400,"step":1,"scale":0,"unit":"s"}
  -- enum:   {"range":["power_off","power_on","last"]}
  -- string: {"maxlen":255}     bitmap: {"labels":["overcurrent","overvoltage"]}
  spec           jsonb    NOT NULL DEFAULT '{}',
  -- {"min_interval_s":10,"change_threshold_pct":5,"qos":0,"history":"change|sample|off",
  --  "offline_queue":false,"energy":"power_w|energy_wh_delta|voltage_v|current_ma",
  --  "notify":true}   (events: raise an alarm notification)
  report_policy  jsonb    NOT NULL DEFAULT '{}',
  is_standard    boolean  NOT NULL DEFAULT true, -- false = vendor-specific DP (ids 101+ by convention)
  PRIMARY KEY (product_id, dp_id),
  UNIQUE (product_id, code)
);

-- -----------------------------------------------------------------------------
-- identity: users, login identities, sessions, OAuth clients   (service: identity)
-- -----------------------------------------------------------------------------

CREATE TABLE identity.users (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  region          text   NOT NULL,               -- home cell, e.g. 'ap-southeast'
  email           citext UNIQUE,
  phone_e164      text   UNIQUE,
  password_hash   text,                          -- argon2id; null for OTP/social-only accounts
  display_name    text   NOT NULL DEFAULT '',
  avatar_url      text,
  locale          text   NOT NULL DEFAULT 'en',
  timezone        text   NOT NULL DEFAULT 'UTC',
  temp_unit       text   NOT NULL DEFAULT 'c' CHECK (temp_unit IN ('c', 'f')),
  signup_app_id   uuid,                          -- -> catalog.apps
  status          text   NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'locked', 'pending_deletion', 'deleted')),
  email_verified_at timestamptz,
  phone_verified_at timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL OR status = 'deleted')
);

CREATE TABLE identity.external_identities (
  provider     text NOT NULL CHECK (provider IN ('google', 'apple', 'facebook')),
  subject      text NOT NULL,                    -- provider's stable user id
  user_id      uuid NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  email        citext,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (provider, subject)
);
CREATE INDEX external_identities_user_idx ON identity.external_identities (user_id);

CREATE TABLE identity.oauth_clients (
  id             text PRIMARY KEY,               -- client_id
  name           text NOT NULL,
  kind           text NOT NULL CHECK (kind IN ('first_party_app', 'voice', 'partner', 'admin')),
  secret_hash    text,                           -- null for public clients (mobile apps use PKCE)
  redirect_uris  text[] NOT NULL DEFAULT '{}',
  scopes         text[] NOT NULL DEFAULT '{}',   -- 'devices:read', 'devices:control', 'homes:read', ...
  app_id         uuid,                           -- -> catalog.apps for first-party apps
  created_at     timestamptz NOT NULL DEFAULT now()
);

-- One row per refresh-token family (one login on one phone / one linked integration).
CREATE TABLE identity.sessions (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id             uuid NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  client_id           text NOT NULL REFERENCES identity.oauth_clients (id),
  refresh_token_hash  bytea NOT NULL UNIQUE,     -- sha256 of the current refresh token
  previous_token_hash bytea,                     -- reuse of this one => revoke the family
  scopes              text[] NOT NULL DEFAULT '{}',
  device_name         text,
  ip                  inet,
  created_at          timestamptz NOT NULL DEFAULT now(),
  last_used_at        timestamptz NOT NULL DEFAULT now(),
  expires_at          timestamptz NOT NULL,
  revoked_at          timestamptz
);
CREATE INDEX sessions_user_idx ON identity.sessions (user_id) WHERE revoked_at IS NULL;

-- -----------------------------------------------------------------------------
-- home: homes, rooms, members, invitations   (service: home)
-- -----------------------------------------------------------------------------

CREATE TABLE home.homes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id    uuid NOT NULL,                     -- -> identity.users
  name        text NOT NULL,
  timezone    text NOT NULL,                     -- IANA name; drives schedules, sunrise/sunset, energy days
  latitude    numeric(8, 5),
  longitude   numeric(8, 5),
  address     text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz
);
CREATE INDEX homes_owner_idx ON home.homes (owner_id) WHERE deleted_at IS NULL;

CREATE TABLE home.rooms (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  home_id     uuid NOT NULL REFERENCES home.homes (id) ON DELETE CASCADE,
  name        text NOT NULL,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX rooms_home_idx ON home.rooms (home_id);

CREATE TABLE home.members (
  home_id     uuid NOT NULL REFERENCES home.homes (id) ON DELETE CASCADE,
  user_id     uuid NOT NULL,                     -- -> identity.users
  role        text NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
  -- members only: restrict to some rooms (null = whole home)
  room_ids    uuid[],
  nickname    text,
  joined_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (home_id, user_id)
);
CREATE INDEX members_user_idx ON home.members (user_id);
-- exactly one owner per home
CREATE UNIQUE INDEX members_one_owner_idx ON home.members (home_id) WHERE role = 'owner';

CREATE TABLE home.invitations (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  home_id         uuid NOT NULL REFERENCES home.homes (id) ON DELETE CASCADE,
  code            text NOT NULL UNIQUE,          -- short code / deep-link token
  role            text NOT NULL CHECK (role IN ('admin', 'member')),
  invited_by      uuid NOT NULL,                 -- -> identity.users
  invitee_contact text,                          -- email or phone, optional
  expires_at      timestamptz NOT NULL,
  accepted_by     uuid,
  accepted_at     timestamptz,
  revoked_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX invitations_home_idx ON home.invitations (home_id);

-- -----------------------------------------------------------------------------
-- device: licenses, devices, shadows, shares, groups   (services: device-registry, shadow)
-- -----------------------------------------------------------------------------

CREATE TABLE device.license_batches (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id  text NOT NULL,                     -- -> catalog.products
  vendor_id   uuid NOT NULL,                     -- -> catalog.vendors
  quantity    integer NOT NULL CHECK (quantity > 0),
  factory     text,
  note        text,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  created_by  uuid NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- Factory identity flashed into each module. Generated in batches and exported
-- to the factory as an encrypted file.
CREATE TABLE device.licenses (
  uuid                text PRIMARY KEY,          -- 20 chars, printed as QR on the device label
  auth_key_enc        bytea NOT NULL,
  batch_id            uuid NOT NULL REFERENCES device.license_batches (id),
  product_id          text NOT NULL,             -- -> catalog.products (may be re-assigned before first use)
  mac                 macaddr,
  status              text NOT NULL DEFAULT 'unused' CHECK (status IN ('unused', 'in_use', 'revoked')),
  activation_count    integer NOT NULL DEFAULT 0,
  first_activated_at  timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX licenses_batch_idx ON device.licenses (batch_id);

-- One row per ACTIVATION. Re-pairing the same hardware creates a new row (new id,
-- new secrets); the old row becomes 'unbound'. History keyed by device id is
-- therefore never visible to a later owner.
CREATE TABLE device.devices (
  id               text PRIMARY KEY,             -- 22 chars, 'nd' + base32; used in MQTT topics
  license_uuid     text REFERENCES device.licenses (uuid),   -- null for sub-devices
  product_id       text NOT NULL,                -- -> catalog.products
  gateway_id       text REFERENCES device.devices (id),      -- set for sub-devices
  node_id          text,                         -- Zigbee IEEE / BLE MAC under its gateway
  home_id          uuid,                         -- -> home.homes
  room_id          uuid,                         -- -> home.rooms
  owner_id         uuid NOT NULL,                -- -> identity.users (the user who paired it)
  name             text NOT NULL,
  icon_url         text,
  secret_enc       bytea,                        -- MQTT deviceSecret; null for sub-devices
  local_key_enc    bytea,                        -- LAN control key
  firmware         jsonb NOT NULL DEFAULT '{}',  -- {"main":"1.4.2","mcu":"1.0.7"}
  thing_model_ver  integer NOT NULL DEFAULT 1,
  mac              macaddr,
  timezone         text,                         -- override; default is the home's
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled', 'unbound')),
  activated_at     timestamptz NOT NULL DEFAULT now(),
  last_online_at   timestamptz,
  unbound_at       timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CHECK ((gateway_id IS NULL) = (node_id IS NULL)),
  CHECK (status = 'unbound' OR home_id IS NOT NULL)
);
-- a piece of hardware can be bound only once at a time
CREATE UNIQUE INDEX devices_license_bound_idx ON device.devices (license_uuid)
  WHERE status <> 'unbound' AND license_uuid IS NOT NULL;
CREATE UNIQUE INDEX devices_node_bound_idx ON device.devices (gateway_id, node_id)
  WHERE status <> 'unbound' AND gateway_id IS NOT NULL;
CREATE INDEX devices_home_idx    ON device.devices (home_id, room_id) WHERE status = 'active';
CREATE INDEX devices_owner_idx   ON device.devices (owner_id) WHERE status <> 'unbound';
CREATE INDEX devices_gateway_idx ON device.devices (gateway_id) WHERE gateway_id IS NOT NULL;
CREATE INDEX devices_product_fw_idx ON device.devices (product_id, ((firmware ->> 'main')))
  WHERE status = 'active';                       -- OTA campaign targeting

-- Durable copy of the shadow. Redis holds the hot copy; the shadow service
-- writes here in batches (write-behind, at most every 5 s per device).
CREATE TABLE device.shadows (
  device_id      text PRIMARY KEY REFERENCES device.devices (id) ON DELETE CASCADE,
  reported       jsonb  NOT NULL DEFAULT '{}',   -- {"switch_1":true,"cur_power":125.0}  (codes, scaled)
  reported_meta  jsonb  NOT NULL DEFAULT '{}',   -- {"switch_1":{"ts":1762480001200,"src":"local"}}
  desired        jsonb  NOT NULL DEFAULT '{}',   -- only DPs with offline_queue=true
  version        bigint NOT NULL DEFAULT 0,
  updated_at     timestamptz NOT NULL DEFAULT now()
);

-- Sharing a single device with someone who is not a home member.
CREATE TABLE device.shares (
  device_id   text NOT NULL REFERENCES device.devices (id) ON DELETE CASCADE,
  user_id     uuid NOT NULL,                     -- -> identity.users
  permission  text NOT NULL CHECK (permission IN ('view', 'control')),
  granted_by  uuid NOT NULL,
  expires_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (device_id, user_id)
);
CREATE INDEX shares_user_idx ON device.shares (user_id);

-- Groups: control many same-category devices as one ("All living room lights").
CREATE TABLE device.groups (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  home_id        uuid NOT NULL,                  -- -> home.homes
  room_id        uuid,
  category_code  text NOT NULL,                  -- -> catalog.categories
  name           text NOT NULL,
  -- Zigbee/BLE mesh groups executed by the gateway in one radio frame
  gateway_id     text REFERENCES device.devices (id),
  local_group_no integer,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX groups_home_idx ON device.groups (home_id);

CREATE TABLE device.group_members (
  group_id   uuid NOT NULL REFERENCES device.groups (id) ON DELETE CASCADE,
  device_id  text NOT NULL REFERENCES device.devices (id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, device_id)
);
CREATE INDEX group_members_device_idx ON device.group_members (device_id);

-- -----------------------------------------------------------------------------
-- automation: scenes, automations, trigger index, schedules   (services: automation, scheduler)
-- -----------------------------------------------------------------------------

-- Scenes (tap-to-run) and automations share one table; a scene simply has no
-- conditions. Conditions/actions are JSON documents validated by the service
-- against docs/architecture/04-backend-services.md §Automation.
CREATE TABLE automation.rules (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  home_id           uuid NOT NULL,               -- -> home.homes
  kind              text NOT NULL CHECK (kind IN ('scene', 'automation')),
  name              text NOT NULL,
  icon              text,
  color             text,
  enabled           boolean NOT NULL DEFAULT true,
  match             text NOT NULL DEFAULT 'any' CHECK (match IN ('any', 'all')),
  conditions        jsonb NOT NULL DEFAULT '[]',
  preconditions     jsonb NOT NULL DEFAULT '[]', -- effective period, e.g. only 18:00-23:00 on weekdays
  actions           jsonb NOT NULL,              -- ordered list, may include delays
  -- what a new trigger does while a run (e.g. a delay) is still pending
  run_mode          text NOT NULL DEFAULT 'restart' CHECK (run_mode IN ('restart', 'single', 'parallel')),
  execution        text NOT NULL DEFAULT 'cloud' CHECK (execution IN ('cloud', 'local')),
  local_gateway_id  text,                        -- -> device.devices, when execution = 'local'
  sort_order        integer NOT NULL DEFAULT 0,
  version           integer NOT NULL DEFAULT 1,
  created_by        uuid NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CHECK (kind = 'automation' OR conditions = '[]'::jsonb),
  CHECK (execution = 'cloud' OR local_gateway_id IS NOT NULL)
);
CREATE INDEX rules_home_idx ON automation.rules (home_id);

-- Inverted index derived from rules.conditions on save, so the engine can find
-- "which rules care about device X dp Y" with one indexed lookup per event.
CREATE TABLE automation.rule_triggers (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rule_id       uuid NOT NULL REFERENCES automation.rules (id) ON DELETE CASCADE,
  trigger_type  text NOT NULL CHECK (trigger_type IN
                  ('device_dp', 'device_event', 'device_online', 'schedule', 'sun', 'weather', 'geofence')),
  device_id     text,                            -- -> device.devices
  dp_code       text,
  home_id       uuid NOT NULL
);
CREATE INDEX rule_triggers_device_idx ON automation.rule_triggers (device_id, dp_code)
  WHERE device_id IS NOT NULL;
CREATE INDEX rule_triggers_rule_idx ON automation.rule_triggers (rule_id);
CREATE INDEX rule_triggers_weather_idx ON automation.rule_triggers (home_id)
  WHERE trigger_type IN ('weather', 'sun');

-- Every time-based job: device timers, countdowns, schedule-triggered automations,
-- sun events, and delayed actions inside a running automation.
-- Workers claim due rows with FOR UPDATE SKIP LOCKED.
CREATE TABLE automation.schedules (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  home_id        uuid NOT NULL,
  owner_type     text NOT NULL CHECK (owner_type IN ('device_timer', 'rule', 'delayed_action')),
  rule_id        uuid REFERENCES automation.rules (id) ON DELETE CASCADE,
  device_id      text,                           -- -> device.devices (device timers)
  group_id       uuid,                           -- -> device.groups (group timers)
  -- {"type":"once","at":"2026-11-08T07:30:00"}
  -- {"type":"weekly","time":"07:30","days":[1,2,3,4,5]}
  -- {"type":"sun","event":"sunset","offset_min":-15,"days":[0,1,2,3,4,5,6]}
  -- {"type":"interval","every_s":3600}
  spec           jsonb NOT NULL,
  timezone       text  NOT NULL,
  actions        jsonb NOT NULL DEFAULT '[]',    -- for device_timer / delayed_action
  enabled        boolean NOT NULL DEFAULT true,
  next_run_at    timestamptz,
  last_run_at    timestamptz,
  claimed_until  timestamptz,                    -- lease, so a crashed worker's job is retried
  label          text,
  created_by     uuid,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CHECK (owner_type <> 'rule' OR rule_id IS NOT NULL)
);
CREATE INDEX schedules_due_idx    ON automation.schedules (next_run_at) WHERE enabled AND next_run_at IS NOT NULL;
CREATE INDEX schedules_device_idx ON automation.schedules (device_id) WHERE device_id IS NOT NULL;
CREATE INDEX schedules_rule_idx   ON automation.schedules (rule_id) WHERE rule_id IS NOT NULL;

-- -----------------------------------------------------------------------------
-- ota: firmware, campaigns, per-device jobs   (service: ota)
-- -----------------------------------------------------------------------------

CREATE TABLE ota.firmwares (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id             text NOT NULL,          -- -> catalog.products
  module                 text NOT NULL CHECK (module IN ('main', 'mcu', 'sub', 'ble', 'zigbee')),
  version                text NOT NULL,          -- '1.5.0'
  version_code           integer NOT NULL,       -- 10500, for comparisons
  object_key             text NOT NULL,          -- S3 key
  size_bytes             bigint NOT NULL,
  sha256                 bytea  NOT NULL,
  signature              bytea  NOT NULL,        -- Ed25519 over sha256
  min_from_version_code  integer,                -- devices below this need an intermediate image
  release_notes          jsonb NOT NULL DEFAULT '{}',  -- {"en":"...","bn":"..."}
  status                 text NOT NULL DEFAULT 'draft'
                           CHECK (status IN ('draft', 'testing', 'released', 'revoked')),
  created_by             uuid NOT NULL,
  created_at             timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, module, version_code)
);

CREATE TABLE ota.campaigns (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  firmware_id    uuid NOT NULL REFERENCES ota.firmwares (id),
  name           text NOT NULL,
  upgrade_mode   text NOT NULL CHECK (upgrade_mode IN ('silent', 'notify', 'forced')),
  -- {"stages":[1,10,50,100],"stage_wait_h":24,"max_failure_pct":3,"window":{"from":"01:00","to":"05:00"}}
  rollout        jsonb NOT NULL,
  -- {"from_version_codes":[10402,10403],"device_ids":[...],"regions":[...],"vendor_id":"..."}
  target_filter  jsonb NOT NULL DEFAULT '{}',
  status         text NOT NULL DEFAULT 'draft'
                   CHECK (status IN ('draft', 'running', 'paused', 'completed', 'aborted')),
  current_stage  smallint NOT NULL DEFAULT 0,
  starts_at      timestamptz,
  created_by     uuid NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE ota.jobs (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id   uuid NOT NULL REFERENCES ota.campaigns (id) ON DELETE CASCADE,
  device_id     text NOT NULL,                   -- -> device.devices
  stage_no      smallint NOT NULL,
  from_version  text,
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN
                  ('pending', 'offered', 'accepted', 'downloading', 'installing',
                   'succeeded', 'failed', 'cancelled')),
  progress_pct  smallint NOT NULL DEFAULT 0,
  error_code    text,
  attempts      smallint NOT NULL DEFAULT 0,
  offered_at    timestamptz,
  finished_at   timestamptz,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (campaign_id, device_id)
);
CREATE INDEX jobs_device_open_idx ON ota.jobs (device_id)
  WHERE status IN ('pending', 'offered', 'accepted', 'downloading', 'installing');
CREATE INDEX jobs_campaign_status_idx ON ota.jobs (campaign_id, status);

-- -----------------------------------------------------------------------------
-- notify: push tokens, message center, preferences   (service: notification)
-- -----------------------------------------------------------------------------

CREATE TABLE notify.push_tokens (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL,                    -- -> identity.users
  app_id       uuid NOT NULL,                    -- -> catalog.apps (selects FCM/APNs credentials)
  platform     text NOT NULL CHECK (platform IN ('ios', 'android')),
  token        text NOT NULL UNIQUE,
  locale       text NOT NULL DEFAULT 'en',
  app_version  text,
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX push_tokens_user_idx ON notify.push_tokens (user_id);

-- In-app message center. Range-partitioned by month (partitions created ahead
-- of time by pg_partman); old partitions are dropped after 180 days.
CREATE TABLE notify.messages (
  id          uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL,
  home_id     uuid,
  device_id   text,
  category    text NOT NULL CHECK (category IN ('alarm', 'device', 'home', 'system', 'promo')),
  title       text NOT NULL,
  body        text NOT NULL,
  data        jsonb NOT NULL DEFAULT '{}',       -- deep link, image, etc.
  created_at  timestamptz NOT NULL DEFAULT now(),
  read_at     timestamptz,
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE INDEX messages_user_idx ON notify.messages (user_id, created_at DESC);
CREATE TABLE notify.messages_default PARTITION OF notify.messages DEFAULT;

CREATE TABLE notify.preferences (
  user_id      uuid NOT NULL,
  category     text NOT NULL,
  channel      text NOT NULL CHECK (channel IN ('push', 'sms', 'email')),
  enabled      boolean NOT NULL DEFAULT true,
  quiet_hours  jsonb,                            -- {"from":"23:00","to":"07:00","tz":"Asia/Dhaka"}
  PRIMARY KEY (user_id, category, channel)
);

-- -----------------------------------------------------------------------------
-- integration: voice assistants, webhooks   (service: integration)
-- -----------------------------------------------------------------------------

CREATE TABLE integration.linked_accounts (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id            uuid NOT NULL,              -- -> identity.users
  platform           text NOT NULL CHECK (platform IN ('alexa', 'google_home', 'smartthings', 'ifttt')),
  external_user_id   text,
  -- tokens Nestap uses to PUSH state to the platform (Alexa event gateway, Google HomeGraph)
  access_token_enc   bytea,
  refresh_token_enc  bytea,
  token_expires_at   timestamptz,
  status             text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked', 'error')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, platform)
);

CREATE TABLE integration.webhooks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   uuid,                              -- partner-level hook
  user_id     uuid,                              -- or user-level hook
  url         text NOT NULL,
  secret_enc  bytea NOT NULL,                    -- HMAC signing secret for deliveries
  events      text[] NOT NULL,                   -- 'device.state.changed', 'device.presence.changed', ...
  enabled     boolean NOT NULL DEFAULT true,
  failures    integer NOT NULL DEFAULT 0,        -- auto-disable after N consecutive failures
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (vendor_id IS NOT NULL OR user_id IS NOT NULL)
);

-- -----------------------------------------------------------------------------
-- updated_at triggers
-- -----------------------------------------------------------------------------

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'catalog.vendors', 'catalog.apps', 'catalog.products',
    'identity.users',
    'home.homes', 'home.rooms',
    'device.devices', 'device.groups',
    'automation.rules', 'automation.schedules',
    'ota.campaigns', 'ota.jobs',
    'integration.linked_accounts'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER touch_updated_at BEFORE UPDATE ON %s FOR EACH ROW EXECUTE FUNCTION infra.touch_updated_at()', t);
  END LOOP;
END $$;
